 <Dialog open={modal==='search-plans'} onOpenChange={v=>!v&&setModal(null)}>{modal==='search-plans'&&state&&<PlanSearch state={state} request={jsonFetch} onClose={()=>setModal(null)} onOpen={hit=>void openSearchHit(hit)}/>}</Dialog>
